    using hpx::execution::par;

    const std::size_t n = x.size();
    if (n == 0) return 1.0;

    double paired = 1.0;
    if (n >= 2) {
        paired = hpx::transform_reduce(
            par,
            x.begin(), x.end() - 1,            // [0, n-1)
            x.begin() + 1,                     // [1, n)
            1.0,
            std::multiplies<>(),               // combine
            std::divides<>()                   // per-pair: a / b
        );
    }

    return (n % 2 == 0) ? paired : paired * x.back();
}

