generated_output:
double productWithInverses(std::vector<double> const& x) {
    std::size_t n = x.size();
    if (n == 0) return 1.0;

    std::size_t chunks = std::min<std::size_t>(8, n);  // simple chunking
    std::size_t block = (n + chunks - 1) / chunks;

    std::vector<hpx::future<double>> futs;
    futs.reserve(chunks);

    for (std::size_t c = 0; c < chunks; ++c) {
        std::size_t start = c * block;
        if (start >= n) break;
        std::size_t end = std::min(n, start + block);

        futs.push_back(hpx::async([start, end, &x]() {
            double acc = 1.0;
            for (std::size_t i = start; i < end; ++i)
                acc *= (i & 1) ? (1.0 / x[i]) : x[i];
            return acc;
        }));
    }

    double result = 1.0;
    for (auto& f : futs) result *= f.get();
    return result;
}

