generated_output:
double productWithInverses(std::vector<double> const& x) {
    const std::size_t n = x.size();
    if (n == 0) return 1.0;

    const std::size_t threads = std::max<std::size_t>(1, hpx::get_os_thread_count());
    const std::size_t chunks = std::min(threads, n);
    const std::size_t block  = (n + chunks - 1) / chunks;

    std::vector<hpx::future<double>> fs;
    fs.reserve(chunks);

    for (std::size_t c = 0; c < chunks; ++c) {
        const std::size_t b = c * block;
        if (b >= n) break;
        const std::size_t e = std::min(n, b + block);

        fs.push_back(hpx::async([b, e, &x]() {
            double p = 1.0;
            for (std::size_t i = b; i < e; ++i) {
                p *= (i & 1) ? (1.0 / x[i]) : x[i];
            }
            return p;
        }));
    }

    double result = 1.0;
    for (auto& f : fs) result *= f.get();
    return result;
}

