double productWithInverses(std::vector<double> const& x) {
    auto seq = [&](std::size_t b, std::size_t e) {
        double acc = 1.0;
        for (std::size_t i = b; i < e; ++i)
            acc *= (i & 1) ? (1.0 / x[i]) : x[i];
        return acc;
    };

    std::function<double(std::size_t, std::size_t)> prod = [&](std::size_t b, std::size_t e) -> double {
        std::size_t n = e - b;
        if (n <= 2048)
            return seq(b, e);
        std::size_t m = b + n / 2;
        auto left = hpx::async([&]() { return prod(b, m); });
        double right = prod(m, e);
        return left.get() * right;
    };

    return prod(0, x.size());
}

