        double even, odd;
        bool odd_len;
    };
    auto make_seg = [](double v) -> Seg { return {v, 1.0 / v, true}; };
    auto combine = [](Seg const& L, Seg const& R) -> Seg {
        return {
            L.even * (L.odd_len ? R.odd : R.even),
            L.odd  * (L.odd_len ? R.even : R.odd),
            L.odd_len ^ R.odd_len
        };
    };
    Seg id{1.0, 1.0, false};
    Seg total = hpx::transform_reduce(hpx::execution::par,
                                      x.begin(), x.end(),
                                      id, combine, make_seg);
    return total.even;
}

