#include <hpx/hpx_main.hpp>

/* Return the value of the smallest odd number in the vector x.
   Use HPX to compute in parallel.  Assume HPX has already been initialized.
   Examples:

   input: [7, 9, 5, 2, 8, 16, 4, 1]
   output: 1

   input: [8, 36, 7, 2, 11]
   output: 7
*/
int smallestOdd(std::vector<int> const& x) {

generated_output:
int smallestOdd(std::vector<int> const& x) {
    using hpx::execution::par;
    constexpr int INF = std::numeric_limits<int>::max();

    auto step = [](int acc, int v) {
        bool ao = (acc % 2 != 0);
        bool vo = (v % 2 != 0);
        if (ao && vo) return std::min(acc, v);
        if (ao) return acc;
        if (vo) return v;
        return INF;
    };

    int res = hpx::reduce(par, x.begin(), x.end(), INF, step);
    if (res == INF) throw std::runtime_error("No odd number found");
    return res;
}

