generated_output:
double sumOfMinimumElements(std::vector<double> const& x, std::vector<double> const& y) {
    std::size_t n = std::min(x.size(), y.size());
    if (n == 0) return 0.0;

    double sum = 0.0;
    hpx::for_loop(
        hpx::execution::par,
        std::size_t(0), n,
        hpx::reduction(sum, std::plus<double>()),
        [&](std::size_t i, double& acc) {
            acc += std::min(x[i], y[i]);
        }
    );
    return sum;
}

